create table ca_private.weekend_sessions(token_hash text primary key,publication_hash text not null references ca_private.weekend_publications(token_hash) on delete cascade,expires_at timestamptz not null default now()+interval '12 hours');
create index weekend_sessions_publication_idx on ca_private.weekend_sessions(publication_hash);
alter table ca_private.weekend_sessions enable row level security;
revoke all on ca_private.weekend_sessions from public,anon,authenticated;
create function public.ca_v2_exchange_weekend(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$declare snapshot jsonb;session_token text;begin snapshot=public.ca_v2_public_weekend(p_token);if snapshot is null then raise exception 'Schedule link unavailable';end if;delete from ca_private.weekend_sessions where expires_at<now();session_token=encode(extensions.gen_random_bytes(32),'hex');insert into ca_private.weekend_sessions(token_hash,publication_hash) values(encode(extensions.digest(session_token,'sha256'),'hex'),encode(extensions.digest(p_token,'sha256'),'hex'));return jsonb_build_object('session',session_token,'snapshot',snapshot);end $$;
create function public.ca_v2_weekend_session(p_session text) returns jsonb language plpgsql security definer set search_path='' as $$declare lookup_hash text;snapshot jsonb;minute_bucket timestamptz=date_trunc('minute',now());observed_hits integer;begin if length(p_session)<>64 or p_session !~ '^[a-f0-9]+$' then raise exception 'Schedule session unavailable';end if;lookup_hash=encode(extensions.digest(p_session,'sha256'),'hex');select p.snapshot into snapshot from ca_private.weekend_sessions s join ca_private.weekend_publications p on p.token_hash=s.publication_hash where s.token_hash=lookup_hash and s.expires_at>now();if snapshot is null then raise exception 'Schedule session expired. Open the original link again.';end if;insert into ca_private.v2_public_limits(token_hash,bucket,hits) values(lookup_hash,minute_bucket,1) on conflict(token_hash,bucket) do update set hits=v2_public_limits.hits+1 returning v2_public_limits.hits into observed_hits;if observed_hits>60 then raise exception 'Too many requests. Try again shortly.';end if;return snapshot;end $$;
revoke all on function public.ca_v2_exchange_weekend(text),public.ca_v2_weekend_session(text) from public,anon,authenticated;
grant execute on function public.ca_v2_exchange_weekend(text),public.ca_v2_weekend_session(text) to anon,authenticated;
